// The `cargo xtask differential` bootstrap-replace scenario: the user that replaces
// the VM's bootstrap account, declared once for both of the scenario's configs.
//
// `provision/zap.ts` is the first bring-up, run with `--bootstrap` as the bootstrap
// account (`ops`), which the new user copies its keys from. `retired/zap.ts` is the
// steady state once `ops` is gone: the same user, holding the keys it was given as a
// list (`keys.ts`, generated by the harness from the user's own `authorized_keys`,
// never checked in). The two differ in nothing else. The username is mirrored in
// `crates/xtask/src/differential/bootstrap.rs`; change them together.
//
// The target connects as `ZAPDIFF_NEXT_USER` (this user) and, under `--bootstrap`, as
// `ZAPDIFF_USER` (`ops`). Nothing here lives in the kitchen sinks, so the base
// snapshot doesn't depend on it.

import type { SshKeys } from '../../../../src/lib/schema.ts';
import type { ZapBuilder } from '../../../../src/lib/zap.ts';

export const declare_replacement = (zap: ZapBuilder, ssh_keys: SshKeys): void => {
	zap.target({
		host: zap.env('ZAPDIFF_HOST'),
		user: zap.env('ZAPDIFF_NEXT_USER'),
		bootstrap_user: zap.env('ZAPDIFF_USER')
	});
	zap.user({
		id: 'next-user',
		username: 'zapnext',
		shell: '/bin/sh',
		ssh_keys,
		sudo: 'nopasswd'
	});
};
